/** The durable identity of one debit, so that a replay can never debit twice. */
export type ChargeKey =
  | { key: "print"; print_id: PrintId; segment: number; tool: number }
  | {
      key: "unobserved";
      file_name: string;
      generation: number;
      origin: string;
      print_number: number;
      tool: number;
    };

